@Composable
private fun ApproveReportDialog(
    reportId: String,
    currentAdminId: String?,
    sessionGeneration: Long,
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onConfirm: (bonus: Int) -> Unit,
) {
    var bonusText by rememberSaveable(reportId, currentAdminId, sessionGeneration) { mutableStateOf("0") }

    AlertDialog(
        onDismissRequest = { if (!isLoading) onDismiss() },
        title = { Text(stringResource(R.string.admin_report_approve_btn)) },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(stringResource(R.string.admin_report_approve_confirm))
                OutlinedTextField(
                    value = bonusText,
                    onValueChange = { if (it.all { c -> c.isDigit() }) bonusText = it },
                    label = { Text(stringResource(R.string.admin_report_bonus_credits)) },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                )
            }
        },
        confirmButton = {
            Button(
                onClick = { onConfirm(bonusText.toIntOrNull() ?: 0) },
                enabled = !isLoading,
            ) {
                if (isLoading) CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
                else Text(stringResource(R.string.confirm))
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss, enabled = !isLoading) {
                Text(stringResource(R.string.cancel))
            }
        }
    )
}

